cat > src/v4/core/tests/treeshake.test.ts <<'E'
import { build } from "esbuild";
import { expect, test } from "vitest";
import * as core from "zod/v4/core";
import * as z from "zod/v4";

const bundle = async (entry: string) => {
  const result = await build({
    stdin: {
      contents: `import * as z from "${entry}"; console.log(z.boolean().parse(true));`,
      resolveDir: import.meta.dirname,
    },
    bundle: true,
    minify: true,
    format: "esm",
    target: "es2020",
    treeShaking: true,
    write: false,
  });
  return result.outputFiles[0]!.text;
};

test("esbuild drops unused declarations (mini)", async () => {
  const out = await bundle("zod/mini");
  expect(out).toContain("boolean");
  for (const s of ["zod_brand", "MAX_SAFE_INTEGER", "02-29"]) expect(out).not.toContain(s);
});

test("esbuild drops unused registry symbols (classic)", async () => {
  const out = await bundle("zod");
  expect(out).toContain("boolean");
  for (const s of ["ZodOutput", "ZodInput"]) expect(out).not.toContain(s);
});

test("runtime behaviour unchanged", () => {
  expect(core.$brand.description).toBe("zod_brand");
  expect(core.$output.description).toBe("ZodOutput");
  expect(core.$input.description).toBe("ZodInput");
  expect(core.util.NUMBER_FORMAT_RANGES.int32).toEqual([-2147483648, 2147483647]);
  expect(core.regexes.date.flags).toBe("");
  expect(z.iso.date().safeParse("2024-02-29").success).toBe(true);
  expect(z.iso.date().safeParse("2023-02-29").success).toBe(false);
  expect(z.int32().safeParse(2 ** 31).success).toBe(false);
});
